#!/usr/bin/env node
// Bundles shipping's sync from a release tag, with the shims, for the sandboxed
// runner. Reads git, never the working tree. `--check` fails if the committed
// bundle or hash differs. No dependency: it only needs CommonJS.
import {execFileSync} from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../..');
const runner = path.resolve(here, '../blanc/services/sync_runner');
const SHIMS = ['crypto', 'fs', 'path', 'os', 'child_process', 'async_hooks', 'url', 'electron', 'spaces'];
const EXTERNAL = {crypto: 'crypto', 'node:crypto': 'crypto', fs: 'fs', 'node:fs': 'fs', path: 'path', 'node:path': 'path',
  os: 'os', child_process: 'child_process', 'node:async_hooks': 'async_hooks', 'node:url': 'url', electron: 'electron'};

// A value as JavaScript source, safe wherever the bundle is read.
const literal = value => JSON.stringify(value).replace(/[<>\u2028\u2029]/g, c => `\\u${c.charCodeAt(0).toString(16).padStart(4, '0')}`);

export function bundle(tag) {
  const show = file => {
    try { return execFileSync('git', ['-C', root, 'show', `${tag}:${file}`], {encoding: 'utf8', maxBuffer: 1e8, stdio: ['ignore', 'pipe', 'ignore']}); }
    catch { return null; }
  };
  const modules = new Map(), maps = new Map();
  const visit = target => {
    const id = [target, `${target}.js`, `${target}.json`].find(file => modules.has(file) || show(file) != null);
    if (!id) throw Error(`missing ${target}`);
    if (modules.has(id)) return id;
    const source = show(id);
    modules.set(id, source);
    if (id.endsWith('.json')) return id;
    const map = {};
    maps.set(id, map);
    for (const [, name] of source.matchAll(/require\(\s*['"]([^'"]+)['"]\s*\)/g)) {
      if (name.startsWith('.')) map[name] = visit(path.posix.normalize(path.posix.join(path.posix.dirname(id), name)));
      else if (EXTERNAL[name]) map[name] = `shim:${EXTERNAL[name]}`;
      else throw Error(`unknown module ${name} in ${id}`);
    }
    return id;
  };
  visit('src/main/sync.js');
  // Shared Spaces' window and sharing rules, which desktop reaches from main.js.
  visit('src/main/shared-spaces-service.js');
  visit('src/main/shared-spaces-runtime.js');
  visit('src/main/document-policy.js');
  const synced = /const SYNCED_KEYS = (\[[^\]]*\]);/.exec(modules.get('src/main/settings.js'));
  if (!synced) throw Error('SYNCED_KEYS not found in settings.js');
  // startPagePins rides in the settings payload but isn't one of settings.js's own keys.
  const known = literal([...JSON.parse(synced[1].replace(/'/g, '"')), 'startPagePins']);
  const shim = name => fs.readFileSync(path.join(runner, 'shims', `${name}.js`), 'utf8');
  const entries = SHIMS.map(name => `${literal(`shim:${name}`)}:[function(module,exports,require){\n${shim(name)}\n},{}]`);
  for (const id of [...modules.keys()].sort()) {
    const source = modules.get(id);
    if (id === 'package.json') {
      const {productName, version} = JSON.parse(source);
      entries.push(`${literal(id)}:[function(module){module.exports=${literal({productName, version})}},{}]`);
    } else if (id.endsWith('.json')) {
      entries.push(`${literal(id)}:[function(module){module.exports=${literal(JSON.parse(source))}},{}]`);
    } else {
      entries.push(`${literal(id)}:[function(module,exports,require){\n${source}\n},${literal(maps.get(id))}]`);
    }
  }
  return `// Generated by chromium/tools/build-sync-bundle.mjs from ${tag}. Don't edit.
${shim('prelude')}
(function(g){'use strict';const M={${entries.join(',\n')}};const C={};
function load(id){if(C[id])return C[id].exports;const e=M[id];if(!e)throw new Error('no module '+id);const m=C[id]={exports:{}};
e[0](m,m.exports,r=>{const t=e[1][r];if(!t)throw new Error('no require '+r+' in '+id);return load(t)});return m.exports}
g.__require=load;})(globalThis);
${shim('api')}
__keepUnknownSettings(${known});
__require('src/main/sync.js');
__require('shim:electron').__sealFlush();
__require('src/main/sync.js').init();
__listen();
`;
}

export const sha256 = text => crypto.createHash('sha256').update(text).digest('hex');
export const hashHeader = hash => `// Generated by chromium/tools/build-sync-bundle.mjs. Don't edit.
#ifndef BLANC_SERVICES_SYNC_RUNNER_BUNDLE_HASH_H_
#define BLANC_SERVICES_SYNC_RUNNER_BUNDLE_HASH_H_
namespace blanc {
inline constexpr char kBlancSyncBundleSha256[] = "${hash}";
}  // namespace blanc
#endif  // BLANC_SERVICES_SYNC_RUNNER_BUNDLE_HASH_H_
`;

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const tag = JSON.parse(fs.readFileSync(path.resolve(here, '../tracker.json'), 'utf8')).shippingTag;
  const text = bundle(tag), header = hashHeader(sha256(text));
  const bundlePath = path.join(runner, 'generated/sync-bundle.js'), headerPath = path.join(runner, 'bundle_hash.h');
  if (process.argv.includes('--check')) {
    if (fs.readFileSync(bundlePath, 'utf8') !== text || fs.readFileSync(headerPath, 'utf8') !== header) {
      console.error('sync bundle is stale: run node chromium/tools/build-sync-bundle.mjs');
      process.exit(1);
    }
  } else {
    fs.writeFileSync(bundlePath, text);
    fs.writeFileSync(headerPath, header);
  }
  console.log(`${tag}: ${text.length} bytes, ${sha256(text)}`);
}
